from .aws import AwsCollector
from .azure import AzureCollector
from .base import Collection, Collector, CollectorError
from .demo import DemoCollector
from .emulator import EmulatorCollector

LIVE_MODES = ('aws', 'azure')
EMULATOR_MODES = ('aws_emu', 'azure_emu')
# Modes whose data is generated by the app. Implemented changes show up on the next sync, the way a real cloud would after the change.
SIMULATED_MODES = ('demo',) + EMULATOR_MODES
MODES = ('demo', 'aws', 'azure', 'aws_emu', 'azure_emu', 'import')
# Which collection methods each cloud supports. GCP has no live collector yet: use demo or import.
MODES_BY_PROVIDER = {'AWS': ('demo', 'aws', 'aws_emu', 'import'), 'Azure': ('demo', 'azure', 'azure_emu', 'import'), 'GCP': ('demo', 'import')}


def get_collector(mode: str) -> Collector | None:
    return {'demo': DemoCollector, 'aws': AwsCollector, 'azure': AzureCollector, 'aws_emu': lambda: EmulatorCollector('aws_emu'),
            'azure_emu': lambda: EmulatorCollector('azure_emu')}.get(mode, lambda: None)()
